def build(path):
    out = {}
    for i, code in enumerate(["hi", "mr", "te"]):
        out[code] = {k.strip(): v[i].strip() for k, v in E.items()}
    js = ("/* Translations for the interface. Written by an AI: a native speaker should review before launch.\n"
          "   Generated from tools_i18n_data.py. {0} {1} are filled in by the app. */\n"
          "window.I18N = " + json.dumps(out, ensure_ascii=False, indent=0) + ";\n")
    open(path, "w", encoding="utf-8").write(js)
    return len(E)


if __name__ == "__main__":
    here = os.path.dirname(os.path.abspath(__file__))
    print(build(os.path.join(here, "backend", "web", "i18n.js")), "entries")
